            Node("row-neighborhood", "rowNeighborhood", "rowNeighborhood", "Classical predicate decidability defines the local neighborhood for arbitrary Prop-valued incidence, without an incidence-decidability hypothesis.", "def rowNeighborhood (ρ : I → J → Prop) (q : State ρ) (b : J) : Finset I", DescribeRole.Definition),
