            Node("incidence-simplex", "incidenceSimplex", "incidenceSimplex", "The full nonempty-face simplex on the literal finite subset of the original ambient carrier.", "def incidenceSimplex (lambda : Finset I) : PreAbstractSimplicialComplex I", DescribeRole.Definition),
            Node("root-k", "rootK", "rootK", "Nonempty faces lie in the active complement of an actual row neighborhood. Inactive ambient labels remain ghosts.", "def rootK (ρ : I → J → Prop) (q : State ρ) : PreAbstractSimplicialComplex I where\n  faces := {s | s.Nonempty ∧ ∃ b ∈ q.rows, s ⊆ q.active \\ rowNeighborhood ρ q b}\n  isRelLowerSet_faces := by\n    rintro s ⟨hs, b, hb, hsb⟩\n    refine ⟨hs, ?_⟩\n    intro t hts ht\n    exact ⟨ht, b, hb, fun x hx => hsb (hts hx)⟩", DescribeRole.Definition),
            Node("mem-root-k", "mem_rootK", "mem_rootK", "Exact membership presentation for the original-ground root complex; the existential ranges over literal row labels.", "@[simp] theorem mem_rootK (ρ : I → J → Prop) (q : State ρ) (s : Finset I) :\n    s ∈ rootK ρ q ↔\n      s.Nonempty ∧ ∃ b ∈ q.rows, s ⊆ q.active \\ rowNeighborhood ρ q b", DescribeRole.Theorem),
            Node("incidence-dual", "incidenceDual", "incidenceDual", "Nonempty proper active subsets avoiding containment of every row neighborhood.", "def incidenceDual (ρ : I → J → Prop) (q : State ρ) :\n    PreAbstractSimplicialComplex I where\n  faces := {s | s.Nonempty ∧ s ⊂ q.active ∧ ∀ b ∈ q.rows,\n    ¬ rowNeighborhood ρ q b ⊆ s}\n  isRelLowerSet_faces := by\n    rintro s ⟨hs, hproper, hrows⟩\n    refine ⟨hs, ?_⟩\n    intro t hts ht\n    refine ⟨ht, Finset.ssubset_iff_subset_ne.mpr ⟨hts.trans hproper.subset, ?_⟩, ?_⟩\n    · intro he\n      exact hproper.not_ge (he ▸ hts)\n    intro b hb hsub\n    exact hrows b hb (hsub.trans hts)", DescribeRole.Definition),
            Node("root-k-dual", "rootK_dual", "rootK_dual", "The fixed-ground Alexander dual of rootK is exactly incidenceDual, including empty-ground and terminal cases.", "theorem rootK_dual (ρ : I → J → Prop) (q : State ρ) :\n    FiniteAlexanderDualCollapse.dual q.active (rootK ρ q) = incidenceDual ρ q", DescribeRole.Theorem),
            Node("erase-row", "eraseRow", "eraseRow", "Erase one row label and retain the original active vertex ground.", "def eraseRow (ρ : I → J → Prop) (q : State ρ) (c : J) : State ρ", DescribeRole.Definition),
