            Node("erase-row-active", "eraseRow_active", "eraseRow_active", "Row erasure preserves the entire active vertex ground definitionally.", "@[simp] theorem eraseRow_active (ρ : I → J → Prop) (q : State ρ) (c : J) :\n    (eraseRow ρ q c).active = q.active", DescribeRole.Theorem),
