            Node("row-subset", "RowSubset", "RowSubset", "The directional incidence condition N(b) contained in N(c), restricted to the active ground.", "def RowSubset (ρ : I → J → Prop) (q : State ρ) (b c : J) : Prop", DescribeRole.Definition),
