            Node("singleton-row", "SingletonRow", "SingletonRow", "An actual retained row has local neighborhood exactly the singleton apex.", "def SingletonRow (ρ : I → J → Prop) (q : State ρ) (b : J) (a : I) : Prop", DescribeRole.Definition),
            Node("row-subset-neighborhood", "rowSubset_neighborhood", "rowSubset_neighborhood", "Converts row incidence inclusion to inclusion of the actual local neighborhoods.", "theorem rowSubset_neighborhood (ρ : I → J → Prop) (q : State ρ)\n    {b c : J} (h : RowSubset ρ q b c) :\n    rowNeighborhood ρ q b ⊆ rowNeighborhood ρ q c", DescribeRole.Theorem),
            Node("column-subset-neighborhood", "columnSubset_neighborhood", "columnSubset_neighborhood", "The conclusion requires active membership of y. Dominated-column input already supplies it; inactive ambient ghosts give a counterexample without it.", "theorem columnSubset_neighborhood (ρ : I → J → Prop) (q : State ρ)\n    {x y : I} (hy : y ∈ q.active) (h : ColumnSubset ρ q x y) :\n    ∀ b ∈ q.rows, x ∈ rowNeighborhood ρ q b → y ∈ rowNeighborhood ρ q b", DescribeRole.Theorem),
            Node("root-k-empty-rows", "rootK_empty_rows", "rootK_empty_rows", "No retained rows gives the ordinary bottom complex, the VOID case.", "theorem rootK_empty_rows (ρ : I → J → Prop) (q : State ρ) (h : q.rows = ∅) :\n    rootK ρ q = ⊥", DescribeRole.Theorem),
            Node("root-k-full-rows", "rootK_full_rows", "rootK_full_rows", "Nonempty retained rows all equal to the active ground give the ordinary bottom complex, the UNIT case.", "theorem rootK_full_rows (ρ : I → J → Prop) (q : State ρ)\n    (hn : q.rows.Nonempty)\n    (hfull : ∀ b ∈ q.rows, rowNeighborhood ρ q b = q.active) :\n    rootK ρ q = ⊥", DescribeRole.Theorem),
            Node("root-k-empty-row", "rootK_empty_row", "rootK_empty_row", "One empty neighborhood realizes the full simplex on the active ground, without choosing a point on an empty ground.", "theorem rootK_empty_row (ρ : I → J → Prop) (q : State ρ) {b : J}\n    (hb : b ∈ q.rows) (hempty : rowNeighborhood ρ q b = ∅) :\n    rootK ρ q = incidenceSimplex q.active", DescribeRole.Theorem),
            Node("root-k-row-erase", "rootK_row_erase", "rootK_row_erase", "Erase c when N(b) is contained in N(c). Its complement simplex is already contained in the simplex supplied by b.", "theorem rootK_row_erase (ρ : I → J → Prop) (q : State ρ)\n    {b c : J} (hb : b ∈ q.rows) (hc : c ∈ q.rows) (hbc : b ≠ c)\n    (hsub : RowSubset ρ q b c) :\n    rootK ρ q = rootK ρ (eraseRow ρ q c)", DescribeRole.Theorem),
            Node("root-k-column-delete", "rootK_column_delete", "rootK_column_delete", "Literal deletion equals the root complex with y erased from active. Both directions convert erased support and incidence explicitly; the equation retains the established public telescope.", "theorem rootK_column_delete (ρ : I → J → Prop) (q : State ρ)\n    {x y : I} (hy : y ∈ q.active) (hxy : x ≠ y)\n    (hsub : ColumnSubset ρ q x y) :\n    deletion (rootK ρ q) y = rootK ρ (eraseColumn ρ q y)", DescribeRole.Theorem),
            Node("root-k-isolated-cone", "rootK_isolated_cone", "rootK_isolated_cone", "An active isolated column over nonempty rows is an actual cone apex, even when the child ordinary complex is bottom.", "theorem rootK_isolated_cone (ρ : I → J → Prop) (q : State ρ)\n    {x : I} (hx : x ∈ q.active) (hrows : q.rows.Nonempty)\n    (hiso : IsolatedColumn ρ q x) :\n    rootK ρ q = cone x (rootK ρ (eraseColumn ρ q x))", DescribeRole.Theorem),
            Node("pruning", "Pruning", "Pruning", "Seven actual structural constructors: VOID, UNIT, empty row, isolated column, redundant row with child, dominated column with child, singleton row with child. None supplies a desired collapse or output witness.", "inductive Pruning (ρ : I → J → Prop) : State ρ → Type\n  | void (q : State ρ) (hrows : q.rows = ∅) : Pruning ρ q\n  | unit (q : State ρ) (hrows : q.rows.Nonempty)\n      (hfull : ∀ b ∈ q.rows, rowNeighborhood ρ q b = q.active) : Pruning ρ q\n  | emptyRow (q : State ρ) (b : J) (hb : b ∈ q.rows)\n      (hempty : rowNeighborhood ρ q b = ∅) : Pruning ρ q\n  | isolatedColumn (q : State ρ) (x : I) (hx : x ∈ q.active)\n      (hrows : q.rows.Nonempty) (hiso : IsolatedColumn ρ q x) : Pruning ρ q\n  | redundantRow (q : State ρ) (b c : J) (hb : b ∈ q.rows) (hc : c ∈ q.rows)\n      (hbc : b ≠ c) (hsub : RowSubset ρ q b c)\n      (child : Pruning ρ (eraseRow ρ q c)) : Pruning ρ q\n  | dominatedColumn (q : State ρ) (x y : I) (hx : x ∈ q.active)\n      (hy : y ∈ q.active) (hxy : x ≠ y) (hsub : ColumnSubset ρ q x y)\n      (child : Pruning ρ (eraseColumn ρ q y)) : Pruning ρ q\n  | singletonRow (q : State ρ) (b : J) (a : I)\n      (hsingle : SingletonRow ρ q b a)\n      (child : Pruning ρ (singletonChild ρ q a)) : Pruning ρ q", DescribeRole.Definition),
            Node("terminal-tag", "TerminalTag", "TerminalTag", "VOID and UNIT are distinct augmented terminal labels although their ordinary root complexes are both bottom.", "inductive TerminalTag where\n  | void\n  | unit\nderiving DecidableEq", DescribeRole.Definition),
            Node("terminal-law", "TerminalLaw", "TerminalLaw", "VOID records empty rows; UNIT records nonempty rows and full local neighborhoods on the original state.", "def TerminalLaw (ρ : I → J → Prop) (q : State ρ) (tag : TerminalTag) : Prop", DescribeRole.Definition),
            Node("witness", "Witness", "Witness", "A constructed native sequence, separate collapsible core and supported original pivot, plus optional critical face with exact endpoint, nonemptiness, outside and complete proper-boundary conditions.", "structure Witness (ρ : I → J → Prop) (q : State ρ) where\n  endpoint : PreAbstractSimplicialComplex I\n  sequence : Sequence (rootK ρ q) endpoint\n  core : PreAbstractSimplicialComplex I\n  pivot : I\n  pivot_mem : pivot ∈ q.active\n  core_sequence : Sequence core (vertexComplex pivot)\n  critical : Option (Finset I)\n  endpoint_eq_core : critical = none → endpoint = core\n  endpoint_eq_attach : ∀ σ, critical = some σ → endpoint = core ⊔ incidenceSimplex σ\n  critical_nonempty : ∀ σ, critical = some σ → σ.Nonempty\n  critical_outside : ∀ σ, critical = some σ → σ ∉ core\n  critical_boundary : ∀ σ, critical = some σ → ∀ t, t ⊂ σ → t = ∅ ∨ t ∈ core", DescribeRole.Definition),
            Node("result", "Result", "Result", "Either a truthful terminal tag with original-state law and bottom equation, or an ordinary regular geometric witness.", "inductive Result (ρ : I → J → Prop) (q : State ρ) where\n  | terminal (tag : TerminalTag) (hK : rootK ρ q = ⊥)\n      (hLaw : TerminalLaw ρ q tag) : Result ρ q\n  | regular (w : Witness ρ q) : Result ρ q", DescribeRole.Definition),
            Node("augmented-terminal", "augmentedTerminal", "augmentedTerminal", "VOID has only ordinary root membership. UNIT restores the empty face solely in this augmented predicate.", "def augmentedTerminal (ρ : I → J → Prop) (q : State ρ) (tag : TerminalTag)\n    (s : Finset I) : Prop", DescribeRole.Definition),
            Node("terminal-semantics", "terminal_semantics", "terminal_semantics", "Given the ordinary bottom equation, VOID augmentation is false and UNIT augmentation is precisely the empty face.", "theorem terminal_semantics (ρ : I → J → Prop) {q : State ρ}\n    (tag : TerminalTag) (hK : rootK ρ q = ⊥) (s : Finset I) :\n    augmentedTerminal ρ q tag s ↔\n      match tag with | .void => False | .unit => s = ∅", DescribeRole.Theorem),
            Node("simplex-collapse", "simplexCollapse", "simplexCollapse", "Actual dominated-vertex free-pair sequences recursively erase nonpivot labels, with strictly decreasing active cardinality, ending at the literal pivot vertex complex. In the nonempty erased-ground branch, Classical.choose hrest selects the original label y and Classical.choose_spec hrest proves y ∈ A.erase p. That membership supplies the inequality, native domination and deletion transports, and the strict cardinality decrease. The quotation gives the definition and its proof.\n\nLean definition body:\ndef simplexCollapse : ∀ (A : Finset I) (p : I), p ∈ A →\n    Sequence (incidenceSimplex A) (vertexComplex p)\n  | A, p, hp => by\n      classical\n      by_cases hrest : (A.erase p).Nonempty\n      · let y := Classical.choose hrest\n        have hy := Classical.choose_spec hrest\n        have hpy : p ≠ y := by\n          intro h; exact (Finset.mem_erase.mp hy).1 h.symm\n        let S := sequence (incidenceSimplex A) p y hpy\n          (simplex_extends A hp (Finset.mem_of_mem_erase hy) hpy)\n        let T := simplexCollapse (A.erase y) p\n          (Finset.mem_erase.mpr ⟨hpy, hp⟩)\n        exact S.append (T.cast (simplex_delete A (Finset.mem_of_mem_erase hy)).symm rfl)\n      · have hA : A = {p} := by\n          apply Finset.eq_singleton_iff_nonempty_unique_mem.mpr\n          exact ⟨⟨p, hp⟩, fun x hx => by\n            by_contra hxp\n            exact hrest ⟨x, Finset.mem_erase.mpr ⟨hxp, hx⟩⟩⟩\n        have hK : incidenceSimplex A = vertexComplex p := by\n          rw [hA]\n          exact simplex_singleton p\n        exact (Sequence.refl (incidenceSimplex A)).cast rfl hK\ntermination_by A.card\ndecreasing_by\n  exact Finset.card_erase_lt_of_mem (Finset.mem_of_mem_erase hy)\n", "def simplexCollapse : ∀ (A : Finset I) (p : I), p ∈ A →\n    Sequence (incidenceSimplex A) (vertexComplex p)", DescribeRole.Definition),
            Node("isolated-collapse", "isolatedCollapse", "isolatedCollapse", "Actual domination sequences erase every nonapex active label, with strictly decreasing active cardinality, and collapse the original cone to its actual apex. Classical.choose hrest selects y on the same ambient type and Classical.choose_spec hrest proves y ∈ q.active.erase x. That membership supplies the native domination and deletion transports and the strict cardinality decrease. The row witness obtained inside hK remains local to an equality proof in Prop. The quotation gives the definition and its proof.\n\nLean definition body:\ndef isolatedCollapse : ∀ (ρ : I → J → Prop) (q : State ρ) (x : I),\n    x ∈ q.active → q.rows.Nonempty → IsolatedColumn ρ q x →\n    Sequence (rootK ρ q) (vertexComplex x)\n  | ρ, q, x, hx, hrows, hiso => by\n      classical\n      by_cases hrest : (q.active.erase x).Nonempty\n      · let y := Classical.choose hrest\n        have hy := Classical.choose_spec hrest\n        have hxy : x ≠ y := by\n          intro h; exact (Finset.mem_erase.mp hy).1 h.symm\n        let S := sequence (rootK ρ q) x y hxy\n          (isolated_extends ρ q hx (Finset.mem_of_mem_erase hy) hxy hrows hiso)\n        let T := isolatedCollapse ρ (eraseColumn ρ q y) x\n          (Finset.mem_erase.mpr ⟨hxy, hx⟩) hrows (by\n            intro b hb hxb\n            exact hiso b hb hxb)\n        exact S.append (T.cast (rootK_column_delete ρ q\n          (Finset.mem_of_mem_erase hy) hxy\n          (fun b hb hxb => (hiso b hb hxb).elim)).symm rfl)\n      · have hq : q.active = {x} := by\n          apply Finset.eq_singleton_iff_nonempty_unique_mem.mpr\n          exact ⟨⟨x, hx⟩, fun y hy => by\n            by_contra hyx\n            exact hrest ⟨y, Finset.mem_erase.mpr ⟨hyx, hy⟩⟩⟩\n        have hK : rootK ρ q = vertexComplex x := by\n          apply SetLike.coe_injective\n          ext s\n          constructor\n          · rintro ⟨hs, b, hb, hsb⟩\n            change s = {x}\n            apply Finset.eq_singleton_iff_nonempty_unique_mem.mpr\n            refine ⟨hs, ?_⟩\n            intro z hz\n            have hzA := ((mem_rowComplement ρ q z b).mp (hsb hz)).1\n            rw [hq] at hzA\n            exact Finset.mem_singleton.mp hzA\n          · intro hs\n            change s = {x} at hs\n            subst s\n            obtain ⟨b, hb⟩ := hrows\n            refine ⟨Finset.singleton_nonempty _, b, hb, ?_⟩\n            intro z hz\n            have hzx := Finset.mem_singleton.mp hz\n            subst z\n            exact (mem_rowComplement ρ q x b).mpr ⟨hx, hiso b hb⟩\n        exact (Sequence.refl (rootK ρ q)).cast rfl hK\ntermination_by q.active.card\ndecreasing_by\n  exact Finset.card_erase_lt_of_mem (Finset.mem_of_mem_erase hy)\n", "def isolatedCollapse : ∀ (ρ : I → J → Prop) (q : State ρ) (x : I),\n    x ∈ q.active → q.rows.Nonempty → IsolatedColumn ρ q x →\n    Sequence (rootK ρ q) (vertexComplex x)", DescribeRole.Definition),
            Node("lift-core-to-base", "liftCoreToBase", "liftCoreToBase", "Lift a core sequence over the full base, remove the genuine terminal pair only inside that core, then collapse the base to the same actual pivot. This sequence is separate from the main retained-critical sequence.", "def liftCoreToBase (A : Finset I) (C : PreAbstractSimplicialComplex I)\n    (a p : I) (hCD : C ≤ incidenceSimplex A)\n    (haD : Fresh a (incidenceSimplex A))\n    (S : Sequence C (vertexComplex p))\n    (hpA : p ∈ A) (hap : a ≠ p) :\n    Sequence (incidenceSimplex A ⊔ cone a C) (vertexComplex p)", DescribeRole.Definition),
            Node("singleton-decomposition", "singleton_decomposition", "singleton_decomposition", "With an actual parent apex, every parent face belongs to the full erased-ground base or to the cone over the filtered child, and conversely. The full parent base retains all child-retired labels.", "theorem singleton_decomposition (ρ : I → J → Prop) (q : State ρ)\n    {b : J} (a : I) (hsingle : SingletonRow ρ q b a)\n    (hapex : ({a} : Finset I) ∈ rootK ρ q) :\n    rootK ρ q = incidenceSimplex (q.active.erase a) ⊔\n      cone a (rootK ρ (singletonChild ρ q a))", DescribeRole.Theorem),
            Node("singleton-no-apex", "singleton_no_apex", "singleton_no_apex", "Empty filtered child rows forbid the apex in every parent face and yield exactly the full erased-ground base simplex.", "theorem singleton_no_apex (ρ : I → J → Prop) (q : State ρ)\n    {b : J} (a : I) (hsingle : SingletonRow ρ q b a)\n    (hrows : (singletonChild ρ q a).rows = ∅) :\n    rootK ρ q = incidenceSimplex (q.active.erase a)", DescribeRole.Theorem),
            Node("singleton-apex-of-child-rows", "singleton_apex_of_child_rows", "singleton_apex_of_child_rows", "A retained filtered child row supplies an actual apex singleton in the parent root complex.", "theorem singleton_apex_of_child_rows (ρ : I → J → Prop) (q : State ρ)\n    {b : J} (a : I) (hsingle : SingletonRow ρ q b a)\n    (hrows : (singletonChild ρ q a).rows.Nonempty) :\n    ({a} : Finset I) ∈ rootK ρ q", DescribeRole.Theorem),
            Node("singleton-apex-of-child-face", "singleton_apex_of_child_face", "singleton_apex_of_child_face", "An actual child face supplies a filtered row, hence an actual parent apex singleton.", "theorem singleton_apex_of_child_face (ρ : I → J → Prop) (q : State ρ)\n    {b : J} (a : I) (hsingle : SingletonRow ρ q b a)\n    {s : Finset I} (hs : s ∈ rootK ρ (singletonChild ρ q a)) :\n    ({a} : Finset I) ∈ rootK ρ q", DescribeRole.Theorem),
            Node("build", "build", "build", "Structural recursion on the real Pruning input constructs Result. Parent terminal laws are proved for each row or column transport. The empty-row nonempty-ground branch selects p by Classical.choose hA and obtains p ∈ q.active from Classical.choose_spec hA. Both singleton-row child-terminal branches with U.Nonempty select p by Classical.choose hU and obtain p ∈ U from Classical.choose_spec hU; Finset.mem_of_mem_erase supplies original active membership. The VOID-child branch casts the simplex-collapse main sequence and uses a reflexive separate core sequence. The UNIT-child branch uses a reflexive main sequence and a separate simplex-collapse core sequence, retaining critical singleton {a} and its full boundary laws. Regular singleton lifting uses source and core containments separately, the actual child pivot, explicit critical Option splitting, literal cone/simplex equations, and proper-boundary support. No output or collapse premise is added. The quotation gives the definition and its proof.\n\nLean definition body:\ndef build {ρ : I → J → Prop} : {q : State ρ} → (c : Pruning ρ q) → Result ρ q\n  | q, .void _ hrows =>\n      .terminal .void (rootK_empty_rows ρ q hrows) hrows\n  | q, .unit _ hrows hfull =>\n      .terminal .unit (rootK_full_rows ρ q hrows hfull) ⟨hrows, hfull⟩\n  | q, .emptyRow _ b hb hempty => by\n      classical\n      have hK := rootK_empty_row ρ q hb hempty\n      by_cases hA : q.active.Nonempty\n      · let p := Classical.choose hA\n        have hp := Classical.choose_spec hA\n        exact .regular {\n          endpoint := vertexComplex p\n          sequence := (simplexCollapse q.active p hp).cast hK.symm rfl\n          core := vertexComplex p\n          pivot := p\n          pivot_mem := hp\n          core_sequence := Sequence.refl _\n          critical := none\n          endpoint_eq_core := by intro; rfl\n          endpoint_eq_attach := by intro σ h; cases h\n          critical_nonempty := by intro σ h; cases h\n          critical_outside := by intro σ h; cases h\n          critical_boundary := by intro σ h; cases h }\n      · have hAE : q.active = ∅ := Finset.eq_empty_iff_forall_notMem.mpr (fun x hx => hA ⟨x, hx⟩)\n        have hfull : ∀ c ∈ q.rows, rowNeighborhood ρ q c = q.active := by\n          intro c hc\n          apply Finset.Subset.antisymm\n          · intro x hx\n            exact ((mem_rowNeighborhood ρ q x c).mp hx).1\n          · rw [hAE]\n            exact Finset.empty_subset _\n        exact .terminal .unit (rootK_full_rows ρ q ⟨b, hb⟩ hfull) ⟨⟨b, hb⟩, hfull⟩\n  | q, .isolatedColumn _ x hx hrows hiso => by\n      exact .regular {\n        endpoint := vertexComplex x\n        sequence := isolatedCollapse ρ q x hx hrows hiso\n        core := vertexComplex x\n        pivot := x\n        pivot_mem := hx\n        core_sequence := Sequence.refl _\n        critical := none\n        endpoint_eq_core := by intro; rfl\n        endpoint_eq_attach := by intro σ h; cases h\n        critical_nonempty := by intro σ h; cases h\n        critical_outside := by intro σ h; cases h\n        critical_boundary := by intro σ h; cases h }\n  | q, .redundantRow _ b c hb hc hbc hsub child => by\n      classical\n      have hK := rootK_row_erase ρ q hb hc hbc hsub\n      have hbchild : b ∈ (eraseRow ρ q c).rows := Finset.mem_erase.mpr ⟨hbc, hb⟩\n      cases build child with\n      | terminal tag hchild hLaw =>\n          cases tag with\n          | void =>\n              change (eraseRow ρ q c).rows = ∅ at hLaw\n              rw [hLaw] at hbchild\n              exact (Finset.notMem_empty b hbchild).elim\n          | unit =>\n              change (eraseRow ρ q c).rows.Nonempty ∧\n                (∀ d ∈ (eraseRow ρ q c).rows,\n                  rowNeighborhood ρ (eraseRow ρ q c) d = (eraseRow ρ q c).active) at hLaw\n              have hfull : ∀ d ∈ q.rows, rowNeighborhood ρ q d = q.active := by\n                intro d hd\n                by_cases hdc : d = c\n                · subst d\n                  have hbfull : rowNeighborhood ρ q b = q.active := hLaw.2 b hbchild\n                  apply Finset.Subset.antisymm\n                  · intro x hx\n                    exact ((mem_rowNeighborhood ρ q x c).mp hx).1\n                  · intro x hx\n                    apply rowSubset_neighborhood ρ q hsub\n                    rw [hbfull]\n                    exact hx\n                · exact hLaw.2 d (Finset.mem_erase.mpr ⟨hdc, hd⟩)\n              exact .terminal .unit (hK.trans hchild) ⟨⟨b, hb⟩, hfull⟩\n      | regular w =>\n          exact .regular {\n            endpoint := w.endpoint\n            sequence := w.sequence.cast hK.symm rfl\n            core := w.core\n            pivot := w.pivot\n            pivot_mem := w.pivot_mem\n            core_sequence := w.core_sequence\n            critical := w.critical\n            endpoint_eq_core := w.endpoint_eq_core\n            endpoint_eq_attach := w.endpoint_eq_attach\n            critical_nonempty := w.critical_nonempty\n            critical_outside := w.critical_outside\n            critical_boundary := w.critical_boundary }\n  | q, .dominatedColumn _ x y hx hy hxy hsub child => by\n      classical\n      have hExt : Extends (rootK ρ q) x y := by\n        rintro s ⟨hs, b, hb, hsb⟩ hyS\n        refine ⟨Finset.insert_nonempty _ _, b, hb, ?_⟩\n        intro z hz\n        rcases Finset.mem_insert.mp hz with rfl | hz\n        · refine Finset.mem_sdiff.mpr ⟨hx, ?_⟩\n          intro hxb\n          exact (Finset.mem_sdiff.mp (hsb hyS)).2\n            (columnSubset_neighborhood ρ q hy hsub b hb hxb)\n        · exact hsb hz\n      let P := sequence (rootK ρ q) x y hxy hExt\n      cases build child with\n      | terminal tag hchild hLaw =>\n          cases tag with\n          | void =>\n              have hrows : q.rows = ∅ := hLaw\n              exact .terminal .void (rootK_empty_rows ρ q hrows) hrows\n          | unit =>\n              change (eraseColumn ρ q y).rows.Nonempty ∧\n                (∀ b ∈ (eraseColumn ρ q y).rows,\n                  rowNeighborhood ρ (eraseColumn ρ q y) b = (eraseColumn ρ q y).active) at hLaw\n              have hfull : ∀ b ∈ q.rows, rowNeighborhood ρ q b = q.active := by\n                intro b hb\n                have hρx : ρ x b := by\n                  apply ((mem_rowNeighborhood ρ (eraseColumn ρ q y) x b).mp ?_).2\n                  rw [hLaw.2 b hb]\n                  exact Finset.mem_erase.mpr ⟨hxy, hx⟩\n                apply Finset.Subset.antisymm\n                · intro z hz\n                  exact ((mem_rowNeighborhood ρ q z b).mp hz).1\n                · intro z hz\n                  apply (mem_rowNeighborhood ρ q z b).mpr\n                  refine ⟨hz, ?_⟩\n                  by_cases hzy : z = y\n                  · subst z\n                    exact hsub b hb hρx\n                  · apply ((mem_rowNeighborhood ρ (eraseColumn ρ q y) z b).mp ?_).2\n                    rw [hLaw.2 b hb]\n                    exact Finset.mem_erase.mpr ⟨hzy, hz⟩\n              exact .terminal .unit (rootK_full_rows ρ q hLaw.1 hfull) ⟨hLaw.1, hfull⟩\n      | regular w =>\n          have hdel := rootK_column_delete ρ q hy hxy hsub\n          exact .regular {\n            endpoint := w.endpoint\n            sequence := P.append (w.sequence.cast hdel.symm rfl)\n            core := w.core\n            pivot := w.pivot\n            pivot_mem := Finset.mem_of_mem_erase w.pivot_mem\n            core_sequence := w.core_sequence\n            critical := w.critical\n            endpoint_eq_core := w.endpoint_eq_core\n            endpoint_eq_attach := w.endpoint_eq_attach\n            critical_nonempty := w.critical_nonempty\n            critical_outside := w.critical_outside\n            critical_boundary := w.critical_boundary }\n  | q, .singletonRow _ b a hsingle child => by\n      classical\n      let U := q.active.erase a\n      let D := incidenceSimplex U\n      have haA : a ∈ q.active := singleton_active ρ q hsingle\n      have haD : Fresh a D := fresh_of_active_erase q.active a\n      cases build child with\n      | terminal tag hchild hLaw =>\n          cases tag with\n          | void =>\n              change (singletonChild ρ q a).rows = ∅ at hLaw\n              have hK := singleton_no_apex ρ q a hsingle hLaw\n              by_cases hU : U.Nonempty\n              · let p := Classical.choose hU\n                have hp := Classical.choose_spec hU\n                exact .regular {\n                  endpoint := vertexComplex p\n                  sequence := (simplexCollapse U p hp).cast hK.symm rfl\n                  core := vertexComplex p\n                  pivot := p\n                  pivot_mem := Finset.mem_of_mem_erase hp\n                  core_sequence := Sequence.refl _\n                  critical := none\n                  endpoint_eq_core := by intro; rfl\n                  endpoint_eq_attach := by intro σ h; cases h\n                  critical_nonempty := by intro σ h; cases h\n                  critical_outside := by intro σ h; cases h\n                  critical_boundary := by intro σ h; cases h }\n              · have hUE : U = ∅ := Finset.eq_empty_iff_forall_notMem.mpr (fun x hx => hU ⟨x, hx⟩)\n                have hact : q.active = {a} := by\n                  apply Finset.eq_singleton_iff_nonempty_unique_mem.mpr\n                  refine ⟨⟨a, haA⟩, ?_⟩\n                  intro z hz\n                  by_contra hza\n                  exact hU ⟨z, Finset.mem_erase.mpr ⟨hza, hz⟩⟩\n                have hfull : ∀ c ∈ q.rows, rowNeighborhood ρ q c = q.active := by\n                  intro c hc\n                  have hac : ρ a c := by\n                    by_contra hnot\n                    have hcf : c ∈ (singletonChild ρ q a).rows :=\n                      Finset.mem_filter.mpr ⟨hc, hnot⟩\n                    rw [hLaw] at hcf\n                    exact Finset.notMem_empty c hcf\n                  apply Finset.Subset.antisymm\n                  · intro z hz\n                    exact ((mem_rowNeighborhood ρ q z c).mp hz).1\n                  · intro z hz\n                    have hza : z = a := by\n                      rw [hact] at hz\n                      exact Finset.mem_singleton.mp hz\n                    subst z\n                    exact (mem_rowNeighborhood ρ q a c).mpr ⟨haA, hac⟩\n                exact .terminal .unit (hK.trans (by rw [hUE]; exact simplex_empty))\n                  ⟨⟨b, hsingle.1⟩, hfull⟩\n          | unit =>\n              change (singletonChild ρ q a).rows.Nonempty ∧\n                (∀ c ∈ (singletonChild ρ q a).rows,\n                  rowNeighborhood ρ (singletonChild ρ q a) c =\n                    (singletonChild ρ q a).active) at hLaw\n              have hapex := singleton_apex_of_child_rows ρ q a hsingle hLaw.1\n              have hdec := singleton_decomposition ρ q a hsingle hapex\n              by_cases hU : U.Nonempty\n              · let p := Classical.choose hU\n                have hp := Classical.choose_spec hU\n                let Kparent := D ⊔ cone a (⊥ : PreAbstractSimplicialComplex I)\n                have hparent : rootK ρ q = Kparent := by\n                  rw [hdec, hchild]\n                exact .regular {\n                  endpoint := Kparent\n                  sequence := (Sequence.refl Kparent).cast hparent.symm rfl\n                  core := D\n                  pivot := p\n                  pivot_mem := Finset.mem_of_mem_erase hp\n                  core_sequence := simplexCollapse U p hp\n                  critical := some ({a} : Finset I)\n                  endpoint_eq_core := by intro h; cases h\n                  endpoint_eq_attach := by\n                    intro σ hσ\n                    have he : ({a} : Finset I) = σ := Option.some.inj hσ\n                    subst σ\n                    change D ⊔ cone a (⊥ : PreAbstractSimplicialComplex I) =\n                      D ⊔ incidenceSimplex {a}\n                    rw [cone_bot_simplex]\n                  critical_nonempty := by\n                    intro σ hσ\n                    have he : ({a} : Finset I) = σ := Option.some.inj hσ\n                    subst σ\n                    exact Finset.singleton_nonempty _\n                  critical_outside := by\n                    intro σ hσ hmem\n                    have he : ({a} : Finset I) = σ := Option.some.inj hσ\n                    subst σ\n                    exact haD {a} hmem (Finset.mem_singleton_self _)\n                  critical_boundary := by\n                    intro σ hσ t ht\n                    have he : ({a} : Finset I) = σ := Option.some.inj hσ\n                    subst σ\n                    left\n                    by_contra hne\n                    have hte : t = {a} :=\n                      Finset.eq_singleton_iff_nonempty_unique_mem.mpr\n                        ⟨Finset.nonempty_iff_ne_empty.mpr hne,\n                          fun z hz => Finset.mem_singleton.mp (ht.subset hz)⟩\n                    exact ht.ne hte }\n              · have hUE : U = ∅ := Finset.eq_empty_iff_forall_notMem.mpr (fun x hx => hU ⟨x, hx⟩)\n                have hparent : rootK ρ q = vertexComplex a := by\n                  rw [hdec, hchild]\n                  change incidenceSimplex U ⊔ cone a (⊥ : PreAbstractSimplicialComplex I) = _\n                  simp [hUE, simplex_empty, cone_bot_simplex, simplex_singleton]\n                exact .regular {\n                  endpoint := vertexComplex a\n                  sequence := (Sequence.refl (vertexComplex a)).cast hparent.symm rfl\n                  core := vertexComplex a\n                  pivot := a\n                  pivot_mem := haA\n                  core_sequence := Sequence.refl _\n                  critical := none\n                  endpoint_eq_core := by intro; rfl\n                  endpoint_eq_attach := by intro σ h; cases h\n                  critical_nonempty := by intro σ h; cases h\n                  critical_outside := by intro σ h; cases h\n                  critical_boundary := by intro σ h; cases h }\n      | regular w =>\n          have hsourceD : rootK ρ (singletonChild ρ q a) ≤ D :=\n            rootK_le_full ρ (singletonChild ρ q a)\n          have hcoreRoot : w.core ≤ rootK ρ (singletonChild ρ q a) :=\n            (witness_core_le_endpoint w).trans w.sequence.monotone\n          have hcoreD : w.core ≤ D := hcoreRoot.trans hsourceD\n          have hpU : w.pivot ∈ U := w.pivot_mem\n          have hap : a ≠ w.pivot := by\n            intro he\n            exact (Finset.mem_erase.mp hpU).1 he.symm\n          have hpCore : ({w.pivot} : Finset I) ∈ w.core :=\n            w.core_sequence.monotone (show ({w.pivot} : Finset I) ∈ vertexComplex w.pivot from rfl)\n          have hapex := singleton_apex_of_child_face ρ q a hsingle (hcoreRoot hpCore)\n          have hdec := singleton_decomposition ρ q a hsingle hapex\n          let main := (w.sequence.liftOver D a hsourceD haD).cast hdec.symm rfl\n          let coreSeq := liftCoreToBase U w.core a w.pivot hcoreD haD\n            w.core_sequence hpU hap\n          exact .regular {\n            endpoint := D ⊔ cone a w.endpoint\n            sequence := main\n            core := D ⊔ cone a w.core\n            pivot := w.pivot\n            pivot_mem := Finset.mem_of_mem_erase hpU\n            core_sequence := coreSeq\n            critical := w.critical.map (insert a)\n            endpoint_eq_core := by\n              intro h\n              cases hc : w.critical with\n              | none => rw [w.endpoint_eq_core hc]\n              | some τ => simp [hc] at h\n            endpoint_eq_attach := by\n              intro σ hσ\n              cases hc : w.critical with\n              | none => simp [hc] at hσ\n              | some τ =>\n                  have he : insert a τ = σ := Option.some.inj (by simpa [hc] using hσ)\n                  subst σ\n                  rw [w.endpoint_eq_attach τ hc, cone_sup, cone_simplex, sup_assoc]\n            critical_nonempty := by\n              intro σ hσ\n              cases hc : w.critical with\n              | none => simp [hc] at hσ\n              | some τ =>\n                  have he : insert a τ = σ := Option.some.inj (by simpa [hc] using hσ)\n                  subst σ\n                  exact Finset.insert_nonempty _ _\n            critical_outside := by\n              intro σ hσ hmem\n              cases hc : w.critical with\n              | none => simp [hc] at hσ\n              | some τ =>\n                  have he : insert a τ = σ := Option.some.inj (by simpa [hc] using hσ)\n                  subst σ\n                  have hτU : τ ⊆ U := witness_critical_support w hc\n                  have haτ : a ∉ τ := fun ha => (Finset.mem_erase.mp (hτU ha)).1 rfl\n                  rcases hmem with hD | hcone\n                  · exact haD (insert a τ) hD (Finset.mem_insert_self _ _)\n                  · have haug : AugmentedFace w.core τ := by\n                      simpa only [Finset.erase_insert haτ] using hcone.2\n                    rcases haug with he | hτC\n                    · exact (w.critical_nonempty τ hc).ne_empty he\n                    · exact w.critical_outside τ hc hτC\n            critical_boundary := by\n              intro σ hσ t ht\n              cases hc : w.critical with\n              | none => simp [hc] at hσ\n              | some τ =>\n                  have he : insert a τ = σ := Option.some.inj (by simpa [hc] using hσ)\n                  subst σ\n                  have hτU : τ ⊆ U := witness_critical_support w hc\n                  by_cases hte : t = ∅\n                  · exact Or.inl hte\n                  · right\n                    have htne : t.Nonempty := Finset.nonempty_iff_ne_empty.mpr hte\n                    by_cases hat : a ∈ t\n                    · have het : t.erase a ⊆ τ := by\n                        intro z hz\n                        rcases Finset.mem_insert.mp (ht.subset (Finset.mem_of_mem_erase hz)) with hza | hzτ\n                        · exact ((Finset.mem_erase.mp hz).1 hza).elim\n                        · exact hzτ\n                      have hstrict : t.erase a ⊂ τ := by\n                        refine Finset.ssubset_iff_subset_ne.mpr ⟨het, ?_⟩\n                        intro heq\n                        apply ht.ne\n                        calc\n                          t = insert a (t.erase a) := (Finset.insert_erase hat).symm\n                          _ = insert a τ := congrArg (insert a) heq\n                      exact Or.inr ⟨htne, w.critical_boundary τ hc (t.erase a) hstrict⟩\n                    · exact Or.inl ⟨htne, fun z hz => hτU (by\n                        rcases Finset.mem_insert.mp (ht.subset hz) with hza | hzτ\n                        · exact (hat (hza ▸ hz)).elim\n                        · exact hzτ)⟩ }\ntermination_by structural c\n", "def build {ρ : I → J → Prop} : {q : State ρ} → (c : Pruning ρ q) → Result ρ q", DescribeRole.Definition),
            Node("native-s-d-r", "nativeSDR", "nativeSDR", "Applies the relative strong deformation retraction construction to the main sequence.", "def nativeSDR {ρ : I → J → Prop} {q : State ρ} (w : Witness ρ q) :\n    RelativeSDR (rootK ρ q) w.endpoint w.sequence.monotone", DescribeRole.Definition),
